// SECURE: Security configuration to protect H2 console
package com.example.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@Profile("dev")  // Only active in development profile
public class H2ConsoleSecurityConfig {

    @Bean
    public SecurityFilterChain h2ConsoleFilterChain(HttpSecurity http) throws Exception {
        http
            // ✅ Require authentication for H2 console
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/h2-console/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )

            // ✅ CSRF exemption for H2 console (frame-based UI)
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/h2-console/**")
            )

            // ✅ Allow frames from same origin (H2 console requirement)
            .headers(headers -> headers
                .frameOptions(frame -> frame.sameOrigin())
            );

        return http.build();
    }
}
```

### Tier 3: Production Hardening (20 min)

**Add profile validation and startup checks**

```java
// SECURE: Startup validation to prevent H2 in production
package com.example.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class ProductionSecurityValidator {

    private static final Logger log = LoggerFactory.getLogger(ProductionSecurityValidator.class);

    @Value("${spring.h2.console.enabled:false}")
    private boolean h2ConsoleEnabled;

    @Value("${spring.datasource.url:}")
    private String datasourceUrl;

    private final Environment environment;

    public ProductionSecurityValidator(Environment environment) {
        this.environment = environment;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void validateProductionSecurity() {
        String[] activeProfiles = environment.getActiveProfiles();
        boolean isProduction = java.util.Arrays.asList(activeProfiles).contains("prod");

        if (isProduction) {
            // ✅ Fail fast if H2 enabled in production
            if (h2ConsoleEnabled) {
                String error = "SECURITY VIOLATION: H2 console enabled in production profile";
                log.error(error);
                throw new IllegalStateException(error);
            }

            // ✅ Fail fast if H2 database in production
            if (datasourceUrl != null && datasourceUrl.contains("h2:")) {
                String error = "SECURITY VIOLATION: H2 database configured in production profile";
                log.error(error);
                throw new IllegalStateException(error);
            }

            log.info("✅ Production security validation passed");
        }
    }
}

// SECURE: Integration test
package com.example.config;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.core.env.Environment;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@ActiveProfiles("prod")
public class ProductionSecurityTest {

    @Autowired
    private Environment environment;

    @Autowired
    private ProductionSecurityValidator validator;

    @Test
    public void testH2DisabledInProduction() {
        String h2ConsoleEnabled = environment.getProperty("spring.h2.console.enabled");

        // ✅ H2 console must be false or not set in production
        assertTrue(h2ConsoleEnabled == null || h2ConsoleEnabled.equals("false"),
            "H2 console must be disabled in production profile");
    }

    @Test
    public void testProductionDatabaseNotH2() {
        String datasourceUrl = environment.getProperty("spring.datasource.url");

        // ✅ Production must not use H2 database
        assertFalse(datasourceUrl != null && datasourceUrl.contains("h2:"),
            "Production profile must not use H2 database");
    }

    @Test
    public void testH2ConsoleNotAccessibleWithoutAuth() throws Exception {
        // ✅ Verify H2 console requires authentication
        mockMvc.perform(get("/h2-console"))
            .andExpect(status().isUnauthorized());
    }

    @Test
    public void testJNDIInjectionBlocked() throws Exception {
        // ✅ Verify malicious JDBC URLs rejected
        String maliciousUrl = "jdbc:h2:mem:test;INIT=CREATE ALIAS EXEC AS 'void exec(String cmd) throws Exception {Runtime.getRuntime().exec(cmd);}'";

        // Secure implementation should validate and reject
        assertThrows(Exception.class, () -> {
            DriverManager.getConnection(maliciousUrl);
        });
    }

    @Test
    public void testH2ConsoleFrameOptionsSecure() throws Exception {
        // ✅ Verify frame options prevent clickjacking
        mockMvc.perform(get("/h2-console"))
            .andExpect(header().string("X-Frame-Options", "SAMEORIGIN"));
    }

    @Test
    public void testStartupValidationFailsOnH2InProduction() {
        // ✅ Verify startup fails if H2 enabled in prod profile
        assertThrows(IllegalStateException.class, () -> {
            validator.validateProductionSecurity();
        });
    }
}
```

**Prometheus Alerting Rules**
```yaml
groups:
  - name: h2_console_security
    interval: 30s
    rules:
      - alert: H2ConsoleAccessAttempt
        expr: rate(http_requests_total{path="/h2-console"}[5m]) > 0
        for: 1m
        labels:
          severity: critical
        annotations:
          summary: "H2 console access attempt detected"
          description: "H2 console endpoint accessed. Should be disabled in production."

      - alert: H2ConsoleEnabledInProduction
        expr: spring_h2_console_enabled{profile="prod"} > 0
        for: 1m
        labels:
          severity: critical
        annotations:
          summary: "H2 console enabled in production"
          description: "H2 console is enabled in production profile. Immediate remediation required."

      - alert: H2DatabaseInProduction
        expr: spring_datasource_h2{profile="prod"} > 0
        for: 5m
        labels:
          severity: critical
        annotations:
          summary: "H2 database configured in production"
          description: "H2 in-memory database detected in production. Must use production database."

      - alert: UnauthorizedH2ConsoleAccess
        expr: rate(http_requests_total{path="/h2-console",status="401"}[5m]) > 5
        for: 2m
        labels:
          severity: warning
        annotations:
          summary: "Multiple unauthorized H2 console access attempts"
          description: "More than 5 unauthorized access attempts to H2 console in 5 minutes."

      - alert: JNDIInjectionAttempt
        expr: h2_jdbc_url_contains_init > 0
        for: 1m
        labels:
          severity: critical
        annotations:
          summary: "JNDI injection attempt via H2 JDBC URL"
          description: "JDBC URL contains INIT clause. Possible JNDI injection attempt (CVE-2021-42392)."
```

### Incident Response Procedures

**Scenario: H2 Console Exposed and Exploited in Production**

#### Detection (How to Identify)

**Static Analysis:**
```bash
# Check for H2 console enabled
grep -r "spring.h2.console.enabled=true" src/main/resources/

# Semgrep detection
semgrep --config="p/security-audit" --json src/main/resources/
```

**Runtime Detection:**
```bash
# Check if H2 console is accessible
curl -I https://production-app.com/h2-console
# Should return 404, not 200 OK

# Check Prometheus metrics
curl http://localhost:9090/api/v1/query \
  --data-urlencode 'query=spring_h2_console_enabled' | jq

# Scan access logs for H2 console attempts
grep "/h2-console" /var/log/nginx/access.log | \
  awk '{print $1, $7, $9}' | sort | uniq -c
```

**WAF/IDS Detection:**
```bash
# Check for JNDI injection patterns
grep -iE "INIT=|CREATE ALIAS|Runtime.getRuntime" /var/log/waf.log

# Check for H2 console scans (common paths)
grep -E "/h2-console|/h2" /var/log/access.log | \
  awk '{print $1}' | sort | uniq -c | sort -rn
```

#### Containment (Immediate - <10 minutes)

1. **Block H2 Console Path Immediately**
   ```nginx
   # Emergency nginx block
   location /h2-console {
       deny all;
       return 404;
   }

   # Reload nginx
   nginx -s reload
   ```

2. **Disable H2 Console via Config**
   ```bash
   # Update application.properties
   echo "spring.h2.console.enabled=false" >> application.properties

   # Restart application
   systemctl restart spring-boot-app
   ```

3. **Kill Suspicious Processes**
   ```bash
   # Check for processes spawned via H2 JNDI injection
   ps aux | grep -E "bash|sh|nc|wget|curl" | grep -v grep

   # Kill suspicious child processes
   pstree -p $(pgrep java) | grep -oP '\d+' | xargs kill -9
   ```

4. **Block Attacker IPs**
   ```bash
   # Extract IPs that accessed H2 console
   grep "/h2-console" /var/log/access.log | \
     awk '{print $1}' | sort | uniq > attacker-ips.txt

   # Block via iptables
   while read ip; do iptables -A INPUT -s $ip -j DROP; done < attacker-ips.txt
   ```

#### Investigation (10-60 minutes)

1. **Analyze H2 Console Access Logs**
   ```bash
   # Find all H2 console access attempts
   grep "/h2-console" /var/log/access.log | \
     awk '{print $4, $1, $7, $9}' | sort

   # Check for JNDI injection patterns
   grep -iE "INIT=|CREATE ALIAS|shellexec|Runtime" /var/log/access.log
   ```

2. **Check for Command Execution**
   ```bash
   # Review application logs for executed commands
   grep -iE "exec|runtime|processbuilder" /var/log/app.log

   # Check system command history
   history | grep -E "curl|wget|bash|sh"

   # Check for new files created
   find /opt/app -type f -mtime -1 -ls
   ```

3. **Audit Database Access**
   ```sql
   -- Check for suspicious database activities
   SELECT * FROM database_audit_log
   WHERE timestamp > DATE_SUB(NOW(), INTERVAL 24 HOUR)
   ORDER BY timestamp DESC;
   ```

4. **Check for Persistence Mechanisms**
   ```bash
   # Look for webshells or backdoors
   find /opt/app -name "*.jsp" -o -name "*.jspx" -mtime -1

   # Check cron jobs
   crontab -l
   cat /etc/crontab

   # Check systemd timers
   systemctl list-timers --all
   ```

#### Remediation (1-4 hours)

1. **Deploy Permanent Fix**
   ```bash
   # Update all environments
   git checkout feature/disable-h2-console-production

   # Update application.properties for production
   sed -i '/spring.h2.console.enabled/d' src/main/resources/application.properties
   echo "spring.h2.console.enabled=false" >> src/main/resources/application.properties

   # Build and deploy
   mvn clean package
   systemctl restart spring-boot-app
   ```

2. **Migrate to Production Database**
   ```properties
   # application-prod.properties
   spring.datasource.url=jdbc:postgresql://prod-db:5432/appdb
   spring.datasource.username=${DB_USERNAME}
   spring.datasource.password=${DB_PASSWORD}
   spring.jpa.database-platform=org.hibernate.dialect.PostgreSQLDialect
   ```

3. **Add Startup Validation**
   ```java
   // Deploy ProductionSecurityValidator from Tier 3
   // Ensures H2 never enabled in production again
   ```

4. **Remove Malicious Artifacts**
   ```bash
   # Remove any backdoors or webshells
   find /opt/app -type f -mtime -1 -delete

   # Remove malicious cron jobs
   crontab -r
   ```

#### Post-Incident (4-24 hours)

1. **Security Hardening**
   - Add profile-based configuration validation
   - Implement startup security checks
   - Deploy WAF rules for H2 console paths
   - Add automated security scanning to CI/CD

2. **Policy Updates**
   ```markdown
   # New Security Policy
   - H2 console MUST be disabled in production
   - H2 database MUST NOT be used in production
   - Startup validation MUST check for H2 configuration
   - Security review REQUIRED for database configuration changes
   ```

3. **Preventive Controls**
   ```yaml
   # Add CI/CD security gate
   - name: Check for H2 console in production config
     run: |
       if grep -r "spring.h2.console.enabled=true" src/main/resources/application-prod.properties; then
         echo "ERROR: H2 console enabled in production config"
         exit 1
       fi
   ```

4. **Compliance Reporting**
   - Document incident timeline
   - Notify security team and compliance
   - Update risk register
   - Conduct post-mortem review

**Recovery Time Objectives:**
- Detection to containment: <10 minutes
- H2 console disabled: <15 minutes
- Full remediation: 1-4 hours
- Database migration (if needed): 4-8 hours
- Post-incident review: 1 week
